 <div id="automatic-search-panel" class="hidden"><div class="automatic-controls"><label>Search region<select id="scan-region">${Object.entries(PRESETS).map(([key,value])=>`<option value="${key}">${value.name}</option>`).join('')}<option value="custom" disabled>Drawn region</option></select></label><label>Areas to sample<select id="scan-budget"><option value="12">12 areas</option><option value="24" selected>24 areas</option><option value="48">48 areas</option></select></label><button class="button button-outline button-small" id="draw-search-region">Draw region on globe</button><button class="button button-primary button-small" id="run-automatic-search">${icon('search')} Start terrain search</button></div><p class="discovery-help" id="scan-coverage-help"></p><div id="automatic-results" class="automatic-results"></div></div>
