 if(options.onAutomaticSearch){
  root.querySelector('.discovery-title').innerHTML=icon('search')+'<span>Discover matching locations</span>';
  root.querySelector('.search-tabs').innerHTML='<button data-search-tab="automatic">Automatic search</button><button data-search-tab="manual">Manual search</button>';
  root.querySelector('#automatic-search-panel').innerHTML=`<div class="pair-search-controls"><label>Find Earth analogs for<select id="pair-bodies"><option value="both">Both · Moon &amp; Mars</option><option value="moon">Moon</option><option value="mars">Mars</option></select></label><label>Terrain condition<select id="pair-condition"><option value="balanced">Balanced terrain</option><option value="gentle">Gentle regional terrain</option><option value="rugged">Rugged regional terrain</option></select></label><button class="button button-primary" id="run-automatic-search">${icon('search')} Find matching locations</button></div><div class="pair-search-options"><p>Compare slope patterns and elevation range.</p><details><summary>Advanced options</summary><div class="automatic-controls"><label>Earth search region<select id="scan-region">${Object.entries(PRESETS).map(([key,value])=>'<option value="'+key+'">'+value.name+'</option>').join('')}<option value="custom" disabled>Drawn region</option></select></label><label>Earth areas to sample<select id="scan-budget"><option value="6">6 areas · quick search</option><option value="12" selected>12 areas</option><option value="24">24 areas</option></select></label><button class="button button-outline button-small" id="draw-search-region">Draw Earth region on globe</button></div><p class="discovery-help" id="scan-coverage-help"></p></details></div><div id="automatic-results"></div>`;
  const condition=root.querySelector('#pair-condition');condition.onchange=()=>{root.querySelector('.pair-search-options>p').textContent=condition.value==='gentle'?'Mean regional slope ≤ 2° on both areas.':condition.value==='rugged'?'Relief ≥ 500 m and mean slope ≥ 1° on both areas.':'Compare slope patterns and elevation range.';};const bodySelect=root.querySelector('#pair-bodies');bodySelect.hidden=true;bodySelect.before(Object.assign(document.createElement('div'),{className:'pair-body-buttons',innerHTML:'<button type="button" data-pair-body-choice="moon" aria-pressed="false">Moon</button><button type="button" data-pair-body-choice="mars" aria-pressed="false">Mars</button><button type="button" data-pair-body-choice="both" aria-pressed="true">Both</button>'}));root.querySelectorAll('[data-pair-body-choice]').forEach(button=>button.onclick=()=>{bodySelect.value=button.dataset.pairBodyChoice;root.querySelectorAll('[data-pair-body-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));});

 }
 const $=selector=>root.querySelector(selector);let mode='manual',selected=null,controller=null,operation=0,picking=null,firstCorner=null,customBounds=null,latestManual=null,manualPhase='idle';
 const error=message=>{$('#discovery-error').textContent=message;$('#discovery-error').classList.toggle('hidden',!message);};
 function status(message,fraction=null){$('#discovery-status').classList.remove('hidden');$('#discovery-status-text').textContent=message;const bar=$('#discovery-progress');if(fraction===null)bar.removeAttribute('value');else bar.value=Math.max(0,Math.min(100,fraction*100));}
 function busy(value){options.onManualChange?.();root.querySelectorAll('[data-pair-body-choice]').forEach(button=>button.disabled=value);if(options.onAutomaticSearch)for(const id of ['pair-bodies','pair-condition','scan-region','scan-budget'])$('#'+id).disabled=value;$('#cancel-discovery').classList.toggle('hidden',!value);$('#place-search-button').disabled=value;$('#run-automatic-search').disabled=value;$('#pick-earth-point').disabled=value;$('#draw-search-region').disabled=value;}
 function stopPicking(){picking=null;firstCorner=null;$('#pick-earth-point').textContent='Pick on globe';$('#draw-search-region').textContent='Draw region on globe';options.onPickMode?.(null);}
 function cancel(){controller?.abort();controller=null;operation++;if(mode==='manual')manualPhase=selected?'selected':'idle';busy(false);stopPicking();status('Search cancelled. Completed results are kept.',1);}
