 function setMode(value){if(controller&&!controller.signal.aborted)cancel();mode=value;stopPicking();root.querySelectorAll('[data-search-tab]').forEach(b=>b.classList.toggle('active',b.dataset.searchTab===value));$('#manual-search-panel').classList.toggle('hidden',value!=='manual');$('#automatic-search-panel').classList.toggle('hidden',value!=='automatic');error('');$('#discovery-status').classList.add('hidden');options.onModeChange?.(value);const hint=root.querySelector('.discovery-footer>span');if(options.onAutomaticSearch&&hint)hint.textContent=value==='automatic'?'32 × 32 km areas · 2 km comparison grid · See Sources & coverage for search limits':'32 × 32 km areas · The comparison uses a common grid for both locations';}
 function selectPlace(place){$('#place-results').innerHTML='';selected={lat:Number(place.lat??place.latitude),lon:Number(place.lon??place.longitude),name:place.name||coordinateLabel({lat:place.lat??place.latitude,lon:place.lon??place.longitude}),country:place.country||'Selected Earth location'};latestManual=null;manualPhase='selected';$('#manual-selection').classList.remove('hidden');$('#manual-selection').innerHTML=`<div><span class="eyebrow">SELECTED STUDY AREA</span><h3>${esc(selected.name)}</h3><p>${esc(selected.country)} · ${coordinateLabel(selected)}</p></div><button class="button button-primary button-small" id="analyze-manual-area">Analyze this area ${icon('arrow')}</button>`;$('#analyze-manual-area').onclick=analyzeManual;options.onPreview?.({...selected,bounds:earthBounds(selected.lat,selected.lon)});options.onManualChange?.();}
 async function searchPlaces(event){event?.preventDefault();const query=$('#place-query').value.trim();if(!query)return error('Enter a place name or latitude, longitude.');manualPhase='finding';selected=null;latestManual=null;$('#manual-selection').classList.add('hidden');$('#place-results').innerHTML='';const job=begin();status('Finding locations…');try{const coordinate=parseCoordinates(query);const places=coordinate?[{...coordinate,name:'Selected coordinates',country:'Earth'}]:await findPlaces(query,{signal:job.signal});if(job.id!==operation)return;$('#place-results').innerHTML=places.map((place,index)=>`<button class="place-result" data-place="${index}"><span>${icon('pin')}<strong>${esc(place.name)}</strong><small>${esc(place.country||'Earth')}${place.admin1?' · '+esc(place.admin1):''}</small></span><span>${coordinateLabel({lat:place.lat??place.latitude,lon:place.lon??place.longitude})} ↗</span></button>`).join('');if(!places.length){manualPhase='error';selected=null;$('#manual-selection').classList.add('hidden');status('No matching name found.',1);error('Try a nearby town, enter decimal coordinates, or pick a point on the globe.');}else{manualPhase='selected';status(`${places.length} location${places.length===1?'':'s'} found. Select a study area.`,1);root.querySelectorAll('[data-place]').forEach(button=>button.onclick=()=>selectPlace(places[Number(button.dataset.place)]));if(places.length===1)selectPlace(places[0]);}}catch(reason){if(job.id===operation&&!job.signal.aborted){manualPhase='error';status('Location search stopped. Try another name or coordinates.',1);error(reason.message||'Place search is unavailable. You can still enter coordinates or pick on the globe.');}}finally{if(job.id===operation){busy(false);controller=null;}}}
 async function analyzeManual(){if(!selected)return;manualPhase='loading';const point={...selected},job=begin();status('Reading elevation tiles for your selected area…');const button=$('#analyze-manual-area');if(button)button.disabled=true;try{const result=await loadEarthWindow({...point,origin:'manual',signal:job.signal,onProgress:p=>{if(job.id===operation)status(p.message||`Loading terrain${p.loaded!==undefined?' · '+p.loaded+(p.total?' / '+p.total:'')+' tiles':''}`,p.total?p.loaded/p.total:null);}});if(job.id!==operation)return;latestManual=result;manualPhase='ready';options.onCandidate?.(result,{select:true});const eligible=comparisonStatus(result.site,result.data).scoreEligible;$('#manual-selection').innerHTML=`<div><span class="eyebrow">${eligible?'TERRAIN READY':'COVERAGE REVIEW REQUIRED'}</span><h3>${esc(result.site.name)}</h3><p>${esc(result.site.country)} · ${coordinateLabel(point)}</p><p class="selection-note">${eligible?'Ready in Your comparison below.':'Coverage checks need review. Open Compare to inspect the full-window terrain evidence and coastline findings. Score and inland ranking are withheld.'}</p></div><div class="selection-actions"><button class="button button-primary button-small" id="explore-manual-result">Explore in 3D</button><button class="button button-outline button-small" id="compare-manual-result">Compare evidence</button></div>`;$('#explore-manual-result').onclick=()=>options.onExplore?.(result.site);$('#compare-manual-result').onclick=()=>options.onCompare?.(result.site.id);status('Study area loaded with source metadata.',1);options.toast?.('Your selected terrain is ready.');}catch(reason){if(job.id===operation&&!job.signal.aborted){manualPhase='error';status('Terrain could not be loaded. Try again.',1);error(reason.message||'Could not retrieve this terrain. No estimated heights were substituted.');}}finally{if(job.id===operation){busy(false);controller=null;if(button?.isConnected)button.disabled=false;}}}
 function getRegion(){const key=$('#scan-region').value;return key==='custom'?{name:'Drawn region',bounds:customBounds,step:Math.max(.25,Math.max(customBounds.east-customBounds.west,customBounds.north-customBounds.south)/8)}:PRESETS[key];}
 function updateCoverageHelp(){const region=getRegion();if(!region?.bounds)return;const b=region.bounds;$('#scan-coverage-help').textContent=`${region.name}: ${signed(b.south)}° to ${signed(b.north)}° latitude; ${signed(b.west)}° to ${signed(b.east)}° longitude. Coarse grid centers use up to ${region.step.toFixed(2)}° spacing, then screened for land. This is a bounded survey, not an exhaustive global search.`;options.onRegionPreview?.(b);}
 async function automaticSearch(){if(options.onAutomaticSearch)return automaticPairSearch();const region=getRegion();if(!region?.bounds)return error('Choose or draw a search region first.');const terrain=options.getTargetTerrain?.();if(!terrain)return error('The selected planetary terrain is not ready yet.');const targetName=options.getTargetName?.()||'planetary target',weights={...(options.getWeights?.()||{slope:.65,relief:.35})},job=begin(),rows=[];$('#automatic-results').innerHTML='';status('Screening search centers for land coverage…');try{const result=await scanEarthRegion({bounds:region.bounds,stepDegrees:region.step,maxCandidates:Number($('#scan-budget').value),targetTerrain:terrain,weights,signal:job.signal,onProgress:p=>{if(job.id!==operation)return;const done=p.completed??p.processed??p.loaded??0,total=p.planned??p.total;status(p.message||`Analyzing study areas · ${done}${total?' / '+total:''}`,total?done/total:null);},onResult:item=>{if(job.id!==operation)return;item.site.discovery={type:'sampled-grid',regionName:region.name,bounds:{...region.bounds},stepDegrees:region.step,targetId:terrain.siteId,targetName,weights:{...weights},exhaustive:false,status:'in-progress'};rows.push(item);options.onCandidate?.(item,{select:false});}});if(job.id!==operation)return;const sorted=(result.results||rows).filter(item=>comparisonStatus(item.site,item.data).scoreEligible&&item.comparison).sort((a,b)=>b.comparison.score-a.comparison.score);const review=result.excluded||[],display=[...sorted.slice(0,8),...review];const coverage={...result.coverage,regionName:region.name,targetName,targetId:terrain.siteId,weights,searchType:'sampled-grid',exhaustive:false,candidateIds:[...sorted,...review].map(item=>item.site.id)};options.onScanComplete?.(coverage);$('#automatic-results').innerHTML=`<div class="scan-summary"><strong>${sorted.length} candidate${sorted.length===1?'':'s'} with comparable land coverage</strong><span>Compared with ${esc(targetName)} · ${coverage.cancelled?'cancelled with partial results':'survey complete'}</span><p>${Number(coverage.completed??rows.length)} completed · ${Number(coverage.failed||0)} failed · ${Number(coverage.excluded||0)} need coverage review (unranked) · ${Number(coverage.planned||coverage.attempted||0)} planned centers</p>${display.length?'<button class="button button-outline button-small" id="compare-scan-results">Compare all candidates ↗</button>':''}</div>${display.map((item,index)=>`<button class="scan-result" data-scan-result="${index}"><span class="scan-rank">${item.comparison?index+1:'—'}</span><span><strong>${esc(item.site.name)}</strong><small>${esc(item.site.country)} · ${coordinateLabel(item.site)}</small></span><span class="scan-score">${item.comparison?Number(item.comparison.score).toFixed(1)+'<small>/ 100 terrain index</small>':'Coverage review required<small>Score withheld · inspect evidence</small>'}</span>${icon('arrow')}</button>`).join('')}`;if(display.length)$('#compare-scan-results').onclick=()=>options.onCompare?.(display[0].site.id);root.querySelectorAll('[data-scan-result]').forEach(button=>button.onclick=()=>options.onCompare?.(display[Number(button.dataset.scanResult)].site.id));if(sorted.length)options.onSelect?.(sorted[0].site.id);else if(review.length)options.onSelect?.(review[0].site.id);status(coverage.cancelled?'Survey stopped. Completed evidence remains available.':sorted.length?'Survey complete. Review the terrain evidence.':review.length?'Survey complete. Loaded windows require coverage review; scores withheld.':'Survey complete. No comparable land windows were found.',1);if(!sorted.length&&!review.length)error('No comparable new candidate was found in this sample. Try a different region or use manual coordinates.');}catch(reason){if(job.id===operation&&!job.signal.aborted)error(reason.message||'Automatic search failed. Existing reference candidates were not substituted for search results.');}finally{if(job.id===operation){busy(false);controller=null;}}}

 async function automaticPairSearch(){const region=getRegion();if(!region?.bounds)return error('Choose or draw an Earth region first.');const job=begin();status('Preparing real Earth and planetary data…',0);try{const selected=$('#pair-bodies').value;const result=await options.onAutomaticSearch({bodies:selected==='both'?['moon','mars']:[selected],condition:$('#pair-condition').value,earthBounds:region.bounds,budget:Number($('#scan-budget').value),signal:job.signal,onProgress:p=>{if(job.id===operation)status(p.message,p.fraction);}});if(job.id!==operation)return;status(result.coverage.cancelled?'Search cancelled. Completed pairs remain available.':result.pairs.length?result.pairs.length+' location pairs ready. Select a result below the map.':'No pair found in this sample. Try another region, condition or larger sample.',1);if(!result.pairs.length&&!result.coverage.cancelled)error('No matching pair found. Review exclusions and failures in the search record. No reference sites were substituted.');}catch(reason){if(job.id===operation&&!job.signal.aborted){error(reason.message||'Search could not complete. No estimated heights were substituted.');status('Search stopped. Inspect any completed results and try again.',1);}}finally{if(job.id===operation){busy(false);controller=null;}}}
 function receivePoint(point){if(picking==='point'){stopPicking();$('#place-query').value=`${point.lat.toFixed(5)}, ${point.lon.toFixed(5)}`;selectPlace({...point,name:'Globe-selected location',country:'Earth'});status('Point selected. Analyze the outlined 32 × 32 km study area.',1);}else if(picking==='region'){if(!firstCorner){firstCorner=point;status('First corner selected. Click the opposite corner of your search region.');}else{const a=firstCorner;let west=Math.min(a.lon,point.lon),east=Math.max(a.lon,point.lon);if(east-west>180){west=Math.max(a.lon,point.lon);east=Math.min(a.lon,point.lon)+360;}customBounds={west,east,south:Math.min(a.lat,point.lat),north:Math.max(a.lat,point.lat)};if(customBounds.north-customBounds.south<.1||east-west<.1)return error('Choose a region with a little more width and height.');stopPicking();$('#scan-region option[value="custom"]').disabled=false;$('#scan-region').value='custom';updateCoverageHelp();status('Search region selected. Start a terrain search when ready.',1);}}}
 root.querySelectorAll('[data-search-tab]').forEach(button=>button.onclick=()=>setMode(button.dataset.searchTab));$('#manual-search-form').onsubmit=searchPlaces;root.querySelectorAll('[data-example]').forEach(button=>button.onclick=()=>{$('#place-query').value=button.dataset.example;searchPlaces();});$('#cancel-discovery').onclick=cancel;$('#search-data-sources').onclick=options.onSources;$('#scan-region').onchange=updateCoverageHelp;$('#run-automatic-search').onclick=automaticSearch;
 $('#pick-earth-point').onclick=()=>{if(picking==='point'){stopPicking();return;}picking='point';$('#pick-earth-point').textContent='Cancel point selection';options.onPickMode?.('point',receivePoint);status('Click a location on Earth. Drag to rotate the globe first if needed.');};
 $('#draw-search-region').onclick=()=>{if(picking==='region'){stopPicking();return;}picking='region';firstCorner=null;$('#draw-search-region').textContent='Cancel drawing';options.onPickMode?.('region',receivePoint);status('Click the first corner, then the opposite corner on Earth.');};
 if(options.onAutomaticSearch){setMode('automatic');updateCoverageHelp();}
