 return{root,receivePoint,cancel,clearManualSelection(){selected=null;latestManual=null;manualPhase='idle';if(mode==='manual'&&controller){controller.abort();controller=null;operation++;busy(false);}stopPicking();$('#manual-selection').classList.add('hidden');$('#place-results').innerHTML='';$('#place-query').value='';$('#discovery-status').classList.add('hidden');error('');options.onManualChange?.();},invalidateManual(){selected=null;latestManual=null;manualPhase='editing';$('#manual-selection').classList.add('hidden');options.onManualChange?.();},get manualPhase(){return manualPhase;},get mode(){return mode;},get selected(){return selected;},get latestManual(){return latestManual;},refresh:()=>{if(mode==='automatic')updateCoverageHelp();}};
